/* W10_T01_GOOGLE_TRENDS_V2 */
const rows=$input.all();
const clean=v=>String(v??'').replace(/<[^>]+>/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim();
const traffic=v=>{const s=clean(v).toUpperCase().replace(/,/g,'');const m=s.match(/([0-9.]+)\s*([KM])?/);if(!m)return null;let n=Number(m[1]);if(m[2]==='K')n*=1000;if(m[2]==='M')n*=1000000;return Number.isFinite(n)?n:null;};
const safeDate=v=>{const d=new Date(v||Date.now());return Number.isNaN(d.valueOf())?new Date():d;};
const signals=[];
for(const item of rows){
 const j=item.json||{};const title=clean(j.title);if(!title)continue;
 const observed=safeDate(j.isoDate||j.pubDate||j.published);const metric=traffic(j['ht:approx_traffic']??j.approx_traffic??j.traffic);
 // n8n's RSS node normalises Google Trends item links to the feed URL, so the durable item identity is title + observation timestamp.
 const key=`gb:${title.toLowerCase()}:${observed.toISOString()}`.slice(0,500);
 signals.push({source:'google_trends',source_key:key,country:'GB',title,query:title,source_url:'https://trends.google.com/trending?geo=GB',observed_at:observed.toISOString(),metric_name:'searches',metric_value:metric,raw_data:{traffic:clean(j['ht:approx_traffic']??j.traffic)}});
}
signals.sort((a,b)=>(Number(b.metric_value)||0)-(Number(a.metric_value)||0));
return [{json:{signals:signals.slice(0,20)}}];
